"""Write the measured roster from exported geometry receipts, without rounding gate inputs."""
import json
from pathlib import Path
root=Path('docs/reports/q249'); roll=root/'rollout'
audit=json.loads((roll/'export-audit.json').read_text());census=json.loads((roll/'census.json').read_text());manifest=json.loads(Path('src/assets/manifest.json').read_text());defs={d['id']:d for d in manifest};receipts={r['id']:r for n in range(1,6) for r in json.loads((roll/f'batch-{n}.json').read_text())['receipts']};target=audit['target']
lines=['# q249 — approved heroine proportions across the cast','','PO approved pilot 2 on 10-30: **“Go, roll out.”** Rollout, visual review and final validation are complete. Both head-size upper limits pass for all adult figures; bodies and shoulders remain unchanged.','', '## Accepted policy','',f"The later orchestrator decision supersedes the original lower bounds: head size wins. Both head/height ≤ **{target['headHeight']*1.1:.6f}** and head-width/shoulders ≤ **{target['headShoulder']*1.1:.6f}**. A smaller head is accepted. Bodies and shoulder envelopes are preserved; leg lengths and all body joint positions remain authored. Total crown height naturally decreases when a head shrinks, so leg/total-height changes without lengthening legs.",'', 'The approved heroine and two children are unchanged. Every other adult human asset is covered: **65 variants / 68 figures / 394 source, high, low and LOD files**. Hair/hats/glasses follow their heads; hands are 0.75 about the wrists. Face and eye artwork/materials and texture pixels are retained; eye geometry follows the uniform head scale. Corrections and animation bakes are offline; no per-frame anatomy work is added.','', '## Measurement and source repair','', 'Measurements use mesh vertices in the rig bind pose, including its joint×inverse-bind transforms. The complete head starts below the chin/beard; the shoulder band is frozen from the original arm pivots (−10%/+1.7% of original height). Width is the skull above the head joint; legs are ground to hip. The heroine ratios are head/height **0.272533**, head-width/shoulders **0.871929**, legs/height **0.427527**.','', 'Two source weight maps include clothing in the head region: the long-haired suburban mom uses a reviewed 1.13 m neck plane and a welded neck transition; the crouched crawler uses its forward neck pivot and a front-head selection, rather than treating the shirt collar as its chin. Hooded hazmat/firefighter neck weights blend without widening or narrowing the shoulders. The full face/crown uses one XYZ head scale; the neck connection tapers. Exact per-file data and topology/texture checks are in [export-audit.json](rollout/export-audit.json).','', 'The table compares pre-job geometry `4698e5aa0` with the delivered assets. Lineup before screenshots use the approved pilot-2 checkpoint `168a33a1e`; L1 before scenes and cold-load samples use original main `4698e5aa0`: the blue man is already fixed there; his earlier before/after is retained in [pilot 2](pilot-2/README.md). The legacy male courier row uses his actual `.skin.glb`, matching the in-game player.','', '## Before → after, every figure','', '| Figure | Head / height | Head width / shoulders | Legs / height | XYZ head scale | Binding constraint |','| --- | --- | --- | --- | --- | --- |',f"| Heroine (unchanged) | {target['headHeight']:.4f} → {target['headHeight']:.4f} | {target['headShoulder']:.4f} → {target['headShoulder']:.4f} | {target['legHeight']:.4f} → {target['legHeight']:.4f} | 1.0000 | approved target |"]
compact=[]
for row in census['rows']:
 if row.get('error'):raise RuntimeError(row)
 id=row['id'];name=id+(' / '+row['rootName'] if row.get('rootName') else '')
 if row.get('child'):
  lines.append(f'| {name} | child anatomy retained | child anatomy retained | child anatomy retained | 1.0000 | child exception |');continue
 path=defs[id]['glb'];path=path.replace('.glb','.skin.glb') if id=='char.courier-male' else path
 record=next(r for r in audit['rows'] if r['path']==path);fig=next(f for f in record['figures'] if f.get('rootName')==row.get('rootName'));b,a=fig['before'],fig['after']
 source=receipts.get(id);file=next((f for f in source['files'] if f['path']==path),None) if source else None
 detail=next((f for f in file['figures'] if f.get('rootName')==row.get('rootName')),None) if file else None
 scale=detail['headScale'] if detail else .7879262206602198;binding=('already within both caps' if scale > .99999 else detail['plan']['binding']) if detail else 'approved pilot 2'
 ratio=' | '.join(f"{b[k]:.4f} → {a[k]:.4f}" for k in ['headHeight','headShoulder','legHeight'])
 lines.append(f'| {name} | {ratio} | {scale:.4f} | {binding} |');compact.append({'id':name,'before':b,'after':a,'scale':scale,'binding':binding})
lines+=['', 'The first civilian batch retains the approved pilot scale where it is already smaller than both upper limits; the recorded binding constraint describes the limiting cap, not a requirement to enlarge that head. Source/LOD variation is checked independently in the JSON receipt.','', '## Visual evidence','', '- [Studio front before/after, all 68 figures](rollout/sheets/) — `studio-01.jpg` through `studio-17.jpg`; heroine is on the right within each pair, in the same game metres.','- [Game camera, high and low](rollout/lineup/) — zoom 1.5 and zoom 1 before/after; fixed camera/placement from the baseline. Contact pages are `game15-*`, `game1-*`, `low-game15-*`, `low-game1-*`.','- [L1 depot / PO bench / actual production bench](rollout/l1/) — same camera, seed and frames before/after; [L1 contact pages](rollout/sheets/l1-1.jpg). The morning sitter is already seated at the paused intro. Mugs are 10 cm, held by the updated grip. Caps have a crown and seat on the scalp.','- [Infected and retained corpse views](rollout/corpses/) — all 46 skinned adult variants at both quality tiers. The two original-main corpse comparisons retain the same authored folded poses; this anatomy change does not alter the body pose.','- The approved [pilot-2 studio and idle/walk close sheets](pilot-2/README.md) retain front, 3/4, side, zoom 1.5 and literal 3 m high-tier views. Full-cast extra close files retain a minimum 3 m radius, increased for large monsters; they are not all literal 3 m shots.','', '## Verification','', 'See [QA results](rollout/qa.md). Geometry audit: **394 files, zero errors**, both head caps pass, every measured shoulder envelope is unchanged to the serialization tolerance, triangle counts do not increase, and original texture bytes match. The heroine and children match their original files.','', 'Pipeline PLAYBOOK stage 1 now defines game proportions by the approved heroine and the shrink-only upper-limit rule, rather than the old chibi renders: local pipeline `lane/q249` commit **ce1843b**. No inference, push, GitHub publication or deployment was performed.']
(root/'README.md').write_text('\n'.join(lines)+'\n');(roll/'ratios.json').write_text(json.dumps({'target':target,'rows':compact},indent=2)+'\n')
